using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using Moq;
using Volo.Abp.Cli.Args;
using Volo.Abp.Cli.Commands;
using Xunit;

namespace Volo.Abp.Cli.Tests.Commands;

public class HelpCommandTests
{
    [Fact]
    public async Task ExecuteAsync_TargetIsNullOrWhitespace_LogsUsageInfo()
    {
        // Arrange
        var optionsMock = new Mock<IOptions<AbpCliOptions>>();
        optionsMock.Setup(o => o.Value).Returns(new AbpCliOptions { Commands = new Dictionary<string, Type>() });

        var scopeFactoryMock = new Mock<IServiceScopeFactory>();

        var loggerMock = new Mock<ILogger<HelpCommand>>();

        var helpCommand = new HelpCommand(optionsMock.Object, scopeFactoryMock.Object)
        {
            Logger = loggerMock.Object
        };

        var args = new CommandLineArgs { Target = " " };

        // Act
        await helpCommand.ExecuteAsync(args);

        // Assert
        loggerMock.Verify(
            x => x.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString() == helpCommand.GetUsageInfo()),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
            Times.Once);
    }

    [Fact]
    public async Task ExecuteAsync_TargetNotFound_LogsWarningAndUsageInfo()
    {
        // Arrange
        var commands = new Dictionary<string, Type> { { "existing", typeof(object) } };
        var optionsMock = new Mock<IOptions<AbpCliOptions>>();
        optionsMock.Setup(o => o.Value).Returns(new AbpCliOptions { Commands = commands });

        var scopeFactoryMock = new Mock<IServiceScopeFactory>();

        var loggerMock = new Mock<ILogger<HelpCommand>>();

        var helpCommand = new HelpCommand(optionsMock.Object, scopeFactoryMock.Object)
        {
            Logger = loggerMock.Object
        };

        var args = new CommandLineArgs { Target = "notfound" };

        // Act
        await helpCommand.ExecuteAsync(args);

        // Assert
        loggerMock.Verify(
            x => x.Log(
                LogLevel.Warning,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString() == "There is no command named notfound."),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
            Times.Once);

        loggerMock.Verify(
            x => x.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString() == helpCommand.GetUsageInfo()),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
            Times.Once);
    }

    [Fact]
    public async Task ExecuteAsync_TargetFound_LogsCommandUsageInfo()
    {
        // Arrange
        var commandUsageInfo = "Command usage info";

        var commandMock = new Mock<IConsoleCommand>();
        commandMock.Setup(c => c.GetUsageInfo()).Returns(commandUsageInfo);

        var commands = new Dictionary<string, Type> { { "mycmd", typeof(IConsoleCommand) } };
        var optionsMock = new Mock<IOptions<AbpCliOptions>>();
        optionsMock.Setup(o => o.Value).Returns(new AbpCliOptions { Commands = commands });

        var serviceProviderMock = new Mock<IServiceProvider>();
        serviceProviderMock.Setup(sp => sp.GetRequiredService(typeof(IConsoleCommand))).Returns(commandMock.Object);

        var scopeMock = new Mock<IServiceScope>();
        scopeMock.SetupGet(s => s.ServiceProvider).Returns(serviceProviderMock.Object);

        var scopeFactoryMock = new Mock<IServiceScopeFactory>();
        scopeFactoryMock.Setup(sf => sf.CreateScope()).Returns(scopeMock.Object);

        var loggerMock = new Mock<ILogger<HelpCommand>>();

        var helpCommand = new HelpCommand(optionsMock.Object, scopeFactoryMock.Object)
        {
            Logger = loggerMock.Object
        };

        var args = new CommandLineArgs { Target = "mycmd" };

        // Act
        await helpCommand.ExecuteAsync(args);

        // Assert
        loggerMock.Verify(
            x => x.Log(
                LogLevel.Information,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, t) => v.ToString() == commandUsageInfo),
                null,
                It.IsAny<Func<It.IsAnyType, Exception, string>>()),
            Times.Once);
    }
}
```

AbpCliOptions.Commands is a read-only dictionary property initialized in the constructor. I can add commands to the dictionary after creating the AbpCliOptions instance.

I will update the tests to add commands to the Commands dictionary instead of assigning it.

